function defaultProductMeta(name,unit='斤'){
 const salesSpec=/餐盒/.test(name)?'100个/箱':/可口可乐/.test(name)?'24瓶/箱':/大米/.test(name)?'10kg/袋':/菜刀/.test(name)?'1把/件':/鸡蛋/.test(name)?(unit==='板'?'30枚/板':'约8枚/斤'):unit==='瓶'?'6瓶/件':unit==='包'?'100只/包':unit==='斤'?'500g/斤':`1${unit}/${unit}`;
 const specDescription=/鸡蛋/.test(name)?'30枚/板，约1.5kg':unit==='箱'?'标准整箱包装':unit==='瓶'?'标准瓶装':unit==='袋'?'独立袋装':unit==='包'?'标准包装':unit==='把'?'单件包装':'称重商品，按实际重量计价';
 const productDescription=/鸡蛋/.test(name)?'鲜鸡蛋，轻拿轻放':/白菜|油麦菜|青尖椒|香菇|萝卜/.test(name)?'新鲜到货，常规配送':'常规商品，按订单配送';
 return {salesSpec,specDescription,productDescription};
}
function productDisplayName(name,price,unit){return `${name} ¥${price||'-'}/${unit||'件'}`}
function productCandidates(name,unit,price,meta){
 if(/鸡蛋/.test(name))return [
  {name:'鲜鸡蛋',unit:'板',salesSpec:'30枚/板',specDescription:'30枚/板，约1.5kg',productDescription:'鲜鸡蛋，轻拿轻放',price:'18.50'},
  {name:'鲜鸡蛋',unit:'斤',salesSpec:'约8枚/斤',specDescription:'散装称重，按实际重量计价',productDescription:'鲜鸡蛋，按斤销售',price:'12.00'},
  {name:'土鸡蛋',unit:'斤',salesSpec:'约10枚/斤',specDescription:'小枚土鸡蛋，散装称重',productDescription:'散养土鸡蛋，轻拿轻放',price:'19.00'}
 ];
 const numericPrice=Number(price)||0;
 const compactPrice=numericPrice?(numericPrice*.92).toFixed(2):price;
 const premiumPrice=numericPrice?(numericPrice*1.08).toFixed(2):price;
 return [
  {name,unit,price,salesSpec:meta.salesSpec,specDescription:meta.specDescription,productDescription:meta.productDescription},
  {name,unit,price:compactPrice,salesSpec:meta.salesSpec,specDescription:`小规格${unit}装`,productDescription:`${name}，小包装配送`},
  {name,unit,price:premiumPrice,salesSpec:meta.salesSpec,specDescription:`优选${unit}装`,productDescription:`${name}，优选品质配送`}
 ];
}
